def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    last_m, last_o = history[-1]
    if last_o == 'C':
        return 'C'
    if last_m == 'C':
        if n >= 2:
            prev_m, prev_o = history[-2]
            if prev_m == 'D' and prev_o == 'C':
                return 'C'
        return 'D'
    else:
        dd_streak = 0
        for m, o in reversed(history):
            if m == 'D' and o == 'D':
                dd_streak += 1
            else:
                break
        opp_ever_c = any(o == 'C' for _, o in history)
        threshold = 2 if opp_ever_c else 5
        if dd_streak >= threshold:
            return 'C'
        return 'D'
